<?php else: ?><h2>Make your choice</h2><p class="muted">Select one option. Your vote cannot be changed.</p><form method="post" class="vote-form" data-confirm="Submit your vote? You cannot change it afterwards."><?= token() ?><input type="hidden" name="action" value="vote"><input type="hidden" name="poll_id" value="<?= (int)$p['id'] ?>"><?php foreach($options as $o): ?><label class="vote-option"><input type="radio" name="option_id" value="<?= (int)$o['id'] ?>" required><span><?= e($o['label']) ?></span></label><?php endforeach ?><button class="button">Submit my vote →</button></form><?php endif ?></section><aside class="detail-aside"><section class="panel"><span class="eyebrow">POLL DETAILS</span><dl><dt>Opens</dt><dd><?= e(date_label($p['starts_at'])) ?></dd><dt>Scheduled deadline</dt><dd><?= e(date_label($p['ends_at'])) ?></dd><dt>Participation</dt><dd><?= $total ?> votes submitted</dd><dt>Results</dt><dd><?= $closed?'Published':'Available after closing' ?></dd></dl></section><section class="privacy-note"><strong>One account. One vote.</strong><p>Your choice is recorded securely in the database. Other voters only see aggregate results after closing.</p></section></aside></div>
