n><a href="index.php?page=poll&id=<?= (int)$p['id'] ?>"><?= status($p)==='Closed'?'View results':($p['voted']?'View poll':'Explore poll') ?> ↗</a></div><?php if($page==='admin'): ?><div class="admin-actions"><?php if(!$p['total'] && status($p)!=='Closed'): ?><a href="index.php?page=edit&id=<?= (int)$p['id'] ?>">Edit</a><?php endif ?><?php if(status($p)!=='Closed'): ?><form method="post" data-confirm="Close this poll and publish its results? This cannot be undone."><?= token() ?><input type="hidden" name="action" value="close_poll"><input type="hidden" name="poll_id" value="<?= (int)$p['id'] ?>"><button class="text-btn danger">Close poll</button></form><?php endif ?></div><?php endif ?></article><?php endforeach ?></div><div class="empty" id="no-polls" <?= count($visible)?'hidden':'' ?>><span class="empty-symbol">◈</span><h3>No polls to show yet</h3><p>Try another filter or check back when your community publishes a poll.</p><?php if($page==='admin'): ?><a class="button" href="index.php?page=edit">Create your first poll</a><?php endif ?></div></section>
